    for(const id of ids){const draft=state.connectionDrafts.get(id);if(!draft)continue;for(const key of fields){const entry=draft.get(key);if(entry&&entry.revision<=submitted.draftRevision)draft.delete(key);}if(!draft.size)state.connectionDrafts.delete(id);}
