      const recordId=text(field(decision,'recordId','id'),submitted.payload.id),record=state.records.find(row=>row.id===recordId),reviewId=text(field(decision,'reviewId','lastReviewId'));
      state.undo=reviewId?{recordId,reviewId,stamp:record?.stamp||text(field(decision,'stamp')),action:actionName}:null;
