    $('save-scanner-options').addEventListener('click',()=>{const scanner=$('connection-scanner').value;if(!scanner){showError('Choose a scanner first.');return;}runAction('ScannerSettings',{scanner,name:$('scanner-display-name').value.trim(),path:$('connection-path').value.trim(),drive:$('scanner-drive').value.trim(),username:$('connection-username').value.trim(),dailySchedule:$('daily-schedule').value,activeFrom:$('scanner-active-from').value,expectedMonthly:$('expected-monthly').checked,monthlyDueDay:Number($('monthly-due-day').value),checklist:$('monthly-checklist').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean),excludedDates:$('excluded-dates').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean),checklistEffectiveMonth:$('checklist-effective-month').value});});
