    $('cancel-years').addEventListener('click',()=>$('years-dialog').close());$('all-years').addEventListener('click',()=>{state.years=[];$('year-filter').value='all';$('years-dialog').close();renderReports();});$('apply-years').addEventListener('click',()=>{const years=[...$('year-choices').querySelectorAll('input:checked')].map(input=>input.value);if(!years.length){$('years-error').hidden=false;return;}state.years=years;if(years.length===1){$('year-filter').value=years[0];}else{let option=[...$('year-filter').options].find(item=>item.value==='multiple');if(!option){option=new Option('','multiple');$('year-filter').add(option);}option.textContent=years.join(' + ');$('year-filter').value='multiple';}$('years-dialog').close();renderReports();});
    $('import-profile-button').addEventListener('click',()=>$('profile-file').click());$('profile-file').addEventListener('change',()=>chooseProfile($('profile-file').files[0]));
