    $('open-classic-button').addEventListener('click',()=>runAction('OpenClassic'));$('restore-button').addEventListener('click',()=>runAction('Restore'));$('backup-button').addEventListener('click',()=>runAction('Backup'));$('diagnostics-button').addEventListener('click',()=>runAction('Diagnostics'));$('analyze-button').addEventListener('click',()=>runAction('Analyze'));$('shutdown-button').addEventListener('click',()=>runAction('Shutdown'));
