    const zone=$('update-drop-zone');zone.addEventListener('dragover',event=>{event.preventDefault();if(!isWorking())zone.classList.add('drag-over');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag-over'));zone.addEventListener('drop',event=>{event.preventDefault();zone.classList.remove('drag-over');if(isWorking())return;const files=[...event.dataTransfer.files];if(files.length!==1){showError('Choose one update ZIP at a time.');return;}chooseUpdate(files[0]);});
    $('job-cancel').addEventListener('click',cancelActiveJob);
    $('retry-button').addEventListener('click',()=>{hideError();refreshSnapshot({quiet:false}).catch(showError);});$('dismiss-error').addEventListener('click',hideError);$('job-dismiss').addEventListener('click',()=>{$('job-toast').hidden=true;});
